    singles = [c[0] for c in comps if len(c) == 1]
    return multi, singles

def stamp_cells(grid, cells, anchor=None, point=None):
    """Return {relative_offset: color} placement of cells anchored at `anchor` moved to `point`."""
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    if anchor is None:
        anchor = (min(rs), min(cs))
    dr, dc = point[0] - anchor[0], point[1] - anchor[1]
    return {(r + dr, c + dc): grid[r][c] for r, c in cells}

def stamp_objects_at_points(grid, obj, points, anchor):
    """Stamp a multi-cell object (bbox-center anchored by default) onto each point cell."""
    out = [row[:] for row in grid]
    for p in points:
        for (i, j), v in stamp_cells(grid, obj, anchor, p).items():
            if 0 <= i < len(out) and 0 <= j < len(out[0]):
                out[i][j] = v
    return out

def stamp_shape_on_fitting_spots(grid, color, bg=0):
    """Find the shape drawn in `color` and stamp copies everywhere it fits entirely on background cells."""
    H, W = len(grid), len(grid[0])
    cells = [(i, j) for i in range(H) for j in range(W) if grid[i][j] == color]
    if not cells:
        return [row[:] for row in grid]
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = [(r - r0, c - c0) for r, c in cells]
    out = [row[:] for row in grid]
    for di in range(H):
        for dj in range(W):
            targets = [(di + sr, dj + sc) for sr, sc in shape]
            if all(0 <= i < H and 0 <= j < W and grid[i][j] == bg for i, j in targets):
                for i, j in targets:
                    out[i][j] = color
    return out

def background_off_lines(grid, exclude=()):
    """The most common color in the grid, excluding the given colors (e.g. separator colors)."""
    cnt = Counter(v for row in grid for v in row if v not in exclude)
    return cnt.most_common(1)[0][0]

def separator_lines(grid):
    """Indices of rows and of columns that are one color throughout (full grid lines)."""
    H, W = len(grid), len(grid[0])
    rows = [i for i, r in enumerate(grid) if len(set(r)) == 1]
    cols = [j for j in range(W) if len({r[j] for r in grid}) == 1]
    return rows, cols

def _groups(idxs):
    """Runs of consecutive indices as lists."""
    import itertools
    return [[v for _, v in grp] for _, grp in itertools.groupby(enumerate(idxs), lambda x: x[1] - x[0])]

def block_grid(grid):
    """The grid split by full one-color rows/columns into blocks: list of lists of (rows, cols) index lists."""
    rows, cols = separator_lines(grid)
    R = _groups([i for i in range(len(grid)) if i not in rows])
    C = _groups([j for j in range(len(grid[0])) if j not in cols])
    return [[(r, c) for c in C] for r in R]

def block_stats(grid, fn):
    """A grid with one cell per separator-delimited block, cell = fn(block_cells, block_rows, block_cols)."""
    return [[fn([grid[i][j] for i in r for j in c], r, c) for r, c in row] for row in block_grid(grid)]

def line_runs(cells):
    """Group cells into lines of length >= 2 sharing a row or a column: (lines, horizontal)."""
    from collections import defaultdict
    byrow=defaultdict(list); bycol=defaultdict(list)
    for i,j in cells: byrow[i].append(j); bycol[j].append(i)
    rr={i:sorted(v) for i,v in byrow.items() if len(v)>=2}
    cc={j:sorted(v) for j,v in bycol.items() if len(v)>=2}
    if len(rr)==2 and len(cc)!=2:
        return [[(i,j) for j in rr[i]] for i in sorted(rr)], True
    if len(cc)==2 and len(rr)!=2:
        return [[(i,j) for i in cc[j]] for j in sorted(cc)], False
    return None, None

def paired_beam_fill(grid, junction=4):
    """Two parallel marker runs and seed cells: each seed beams toward its run's cell (seed becomes `junction`),
    and the other run's cell at the same offset beams across the full line; both beams take the seed's color."""
    from collections import Counter
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for r in grid for v in r)
    bg=cnt.most_common(1)[0][0]
    nonbg=[v for v,_ in cnt.most_common() if v!=bg]
    marker=None
    for v in nonbg:
        cells=[(i,j) for i in range(h) for j in range(w) if grid[i][j]==v]
        r,hz=line_runs(cells)
        if r: marker,R,horiz=v,r,hz
    seed=[v for v in nonbg if v!=marker][0]
    d1={k:c for k,c in enumerate(R[0])}; d2={k:c for k,c in enumerate(R[1])}
    out=[row[:] for row in grid]
    for (i,j) in [(i,j) for i in range(h) for j in range(w) if grid[i][j]==seed]:
        out[i][j]=junction
        for D,other in ((d1,d2),(d2,d1)):
            for k,(ri,rj) in D.items():
                if (horiz and j==rj) or (not horiz and i==ri):
                    oi,oj=other[k]
                    if horiz:
                        step=1 if ri>i else -1
                        for x in range(i+step,ri,step): out[x][j]=seed
                        for x in range(h):
                            if x!=oi: out[x][oj]=seed
                    else:
                        step=1 if rj>j else -1
                        for y in range(j+step,rj,step): out[i][y]=seed
                        for y in range(w):
                            if y!=oj: out[oi][y]=seed
                    break
            else: continue
            break
    return out


def recolor_swap_bg_fg_zero(grid):
    """The background becomes the grid's other color, and that other color becomes 0."""
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    fg = next(v for v, _ in cnt.most_common() if v != bg)
    return [[fg if v == bg else (0 if v == fg else v) for v in row] for row in grid]


def recolor_small_to_large_zero(grid):
    """The smaller of the grid's two colors becomes the larger, and the larger becomes 0."""
    vs = {v for row in grid for v in row}
    lo, hi = min(vs), max(vs)
    return [[hi if v == lo else (0 if v == hi else v) for v in row] for row in grid]

def normalize_shape(cells):
    """A cell set as a canonical tuple-of-tuples 0/1 bounding-box mask with its top-left offset."""
    r0 = min(r for r, c in cells); c0 = min(c for r, c in cells)
    H = max(r for r, c in cells) - r0 + 1; W = max(c for r, c in cells) - c0 + 1
    s = {(r - r0, c - c0) for r, c in cells}
    return (r0, c0), tuple(tuple(1 if (r, c) in s else 0 for c in range(W)) for r in range(H))

def is_corner_bar_shape(cells, min_arm=4):
    """True if a cell set contains a horizontal run and a vertical run (each length >= min_arm) sharing a cell that is an endpoint of both (an L)."""
    cells = set(cells)
    from collections import defaultdict
    byrow = defaultdict(list); bycol = defaultdict(list)
    for r, c in cells:
        byrow[r].append(c); bycol[c].append(r)
    hruns = [(r, sorted(cs)) for r, cs in byrow.items() if len(cs) >= min_arm
             and sorted(cs) == list(range(min(cs), max(cs) + 1))]
    vruns = [(c, sorted(rs)) for c, rs in bycol.items() if len(rs) >= min_arm
             and sorted(rs) == list(range(min(rs), max(rs) + 1))]
    for r, cs in hruns:
        for c, rs in vruns:
            if (r, c) in cells and (r, c) in ((r, cs[0]), (r, cs[-1])) and (r, c) in ((rs[0], c), (rs[-1], c)):
                return True
    return False

def min_manhattan(cells_a, cells_b):
    """The smallest Manhattan distance between any cell of each set."""
    return min(abs(r - r2) + abs(c - c2) for r, c in cells_a for r2, c2 in cells_b)

def color_components(grid, bg=None):
    """Per-color 4-connected components of non-background cells: list of (color, cells)."""
    if bg is None:
        bg = background(grid)
    H, W = len(grid), len(grid[0])
    seen = set(); comps = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] != bg and (i, j) not in seen:
                col = grid[i][j]; comp = [(i, j)]; seen.add((i, j)); q = deque([(i, j)])
                while q:
                    a, b = q.popleft()
                    for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        n = (a + da, b + db)
                        if 0 <= n[0] < H and 0 <= n[1] < W and grid[n[0]][n[1]] == col and n not in seen:
                            seen.add(n); comp.append(n); q.append(n)
                comps.append((col, comp))
    return comps

def dihedral_canon(mask):
    """A bounding-box mask canonized over all rotations and reflections."""
    out = []; x = mask
    for _ in range(4):
        out.append(x); out.append([r[::-1] for r in x])
        x = [list(r) for r in zip(*x[::-1])]
    return min(tuple(tuple(r) for r in x) for x in out)

def shape_key(cells):
    """A cell set's shape canonical over rotation/reflection: for grouping same-shaped objects."""
    return dihedral_canon(normalize_shape(cells)[1])

def recolor_farthest_duplicate_to_key(grid, key_shape=None):
    """Recolor, to the smallest corner-bar key object's color, the member farthest from the key of the same-shape group with the largest member (shapes matched over rotation/reflection, objects per-color)."""
    bg = background(grid)
    objs = [{'c': c, 'cells': comp} for c, comp in color_components(grid, bg)]
    keys = [o for o in objs if is_corner_bar_shape(o['cells'], min_arm=4)]
    key = min(keys, key=lambda o: len(o['cells']))
    groups = {}
    for o in objs:
        groups.setdefault(shape_key(o['cells']), []).append(o)
    dups = [v for v in groups.values() if len(v) > 1]
    grp = max(dups, key=lambda v: len(v[0]['cells']))
    tgt = max(grp, key=lambda o: min_manhattan(o['cells'], key['cells']))
    out = [row[:] for row in grid]
    for r, c in tgt['cells']:
        out[r][c] = key['c']
    return out


def hmirror(grid):
    """Each row reversed: the grid mirrored left to right."""
    return [row[::-1] for row in grid]

def vflip(grid):
    """The rows in reverse order: the grid mirrored top to bottom."""
    return grid[::-1]

def hstack(a, b):
    """Two grids of equal height joined side by side."""
    return [ra + rb for ra, rb in zip(a, b)]

def vstack(a, b):
    """Two grids of equal width stacked one above the other."""
    return a + b

def vstack(*grids):
    """Two or more grids of equal width stacked one above the other."""
    out = []
    for g in grids: out += g
    return out

def transpose(grid):
    """Rows and columns exchanged."""
    return [list(r) for r in zip(*grid)]

def rotate_cw(grid, k=1):
    """The grid rotated k quarter-turns clockwise."""
    for _ in range(k % 4):
        grid = transpose(vflip(grid))
    return grid

def rotate_ccw(grid, k=1):
    """The grid rotated k quarter-turns counterclockwise."""
    return rotate_cw(grid, 4 - (k % 4))

def rot180(grid):
    """The grid rotated two quarter-turns."""
    return vflip(hmirror(grid))

def tile_rotations_quadrants(grid):
    """The grid tiled 2x2: top-left as-is, top-right rotated 90 clockwise, bottom-right 180, bottom-left 270."""
    n, w = len(grid), len(grid[0])
    tl = grid
    tr = rotate_cw(grid, 1)
    br = rot180(grid)
    bl = rotate_ccw(grid, 1)
    return vstack(hstack(tl, tr), hstack(bl, br))


def corner_blocks(grid, fill=None):
    """Split the grid by rows/columns carrying rare marker colors; each lattice block gets color c if all 4 corner markers are c, else the fill color."""
    cnt = Counter(v for row in grid for v in row)
    if fill is None:
        fill = cnt.most_common(1)[0][0]
    keep = set(c for c, _ in cnt.most_common()[2:])
    mr = sorted({i for i, row in enumerate(grid) for j, v in enumerate(row) if v in keep})
    mc = sorted({j for row in grid for j, v in enumerate(row) if v in keep})
    out = []
    for a, b in zip(mr, mr[1:]):
        row = []
        for x, y in zip(mc, mc[1:]):
            cs = {grid[a][x], grid[a][y], grid[b][x], grid[b][y]}
            row.append(cs.pop() if len(cs) == 1 and cs <= keep else fill)
        out.append(row)
    return out


def corner_arm_directions(cells):
    """The corner cell of a corner-bar cell set and its two arm directions (sv, sh): the unit steps along each arm."""
    S = set(cells)
    for (r, c) in cells:
        nb = {d for d in [(1, 0), (-1, 0), (0, 1), (0, -1)] if (r + d[0], c + d[1]) in S}
        for v in (1, -1):
            for h in (1, -1):
                if (v, 0) in nb and (0, h) in nb:
                    return (r, c, v, h)

def inside_corner_quadrant(cells, corner):
    """True if every cell of the set lies in the quadrant a corner-bar's arms enclose: strictly along both arm directions from the corner."""
    cr, cc, sv, sh = corner
    return all((r - cr) * sv > 0 and (c - cc) * sh > 0 for r, c in cells)

def recolor_outside_duplicate_to_key(grid, key_shape=None):
    """Recolor, to the smallest corner-bar key object's color, the member(s) of the largest same-shape duplicate group that lie outside the key's enclosed quadrant (shapes matched over rotation/reflection, objects per-color)."""
    bgc = background(grid)
    objs = color_components(grid, bgc)
    keys = [(c, comp) for c, comp in objs if is_corner_bar_shape(comp, min_arm=4)]
    kc, key = min(keys, key=lambda o: len(o[1]))
    corner = corner_arm_directions(key)
    groups = {}
    for c, comp in objs:
        groups.setdefault(shape_key(comp), []).append((c, comp))
    dups = [v for v in groups.values() if len(v) > 1]
    grp = max(dups, key=lambda v: len(v[0][1]))
    out = [row[:] for row in grid]
    for c, comp in grp:
        if not inside_corner_quadrant(comp, corner):
            for r, cc2 in comp:
                out[r][cc2] = kc
    return out

def split_blocks(grid):
    """The two blocks on either side of a single full-height column or full-width row of one color: (orientation, first block, second block)."""
    rows, cols = separator_lines(grid)
    H, W = len(grid), len(grid[0])
    if cols:
        j = cols[0]
        return 'v', [r[:j] for r in grid], [r[j + 1:] for r in grid]
    i = rows[0]
    return 'h', grid[:i], grid[i + 1:]

def shared_color_mark(grid, mark=3):
    """The two blocks split by a full separator line, marked where both blocks show the color they share; that shared color elsewhere."""
    _, A, B = split_blocks(grid)
    shared = ({v for r in A for v in r} & {v for r in B for v in r}).pop()
    return [[mark if a == shared and b == shared else shared for a, b in zip(ra, rb)] for ra, rb in zip(A, B)]


def stamp_marker_motif(grid, bg=None, noise=None, anchor=None):
    """Stamp the grid's small multi-color motif centered on every isolated noise dot."""
    from collections import Counter as _C
    bg = bg if bg is not None else background(grid)
    cnt = _C(v for r in grid for v in r)
    cands = [c for c in cnt if c != bg]
    noise = noise if noise is not None else max(cands, key=lambda c: cnt[c])
    ys = [y for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    xs = [x for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    motif = [row[x0:x1 + 1] for row in grid[y0:y1 + 1]]
    H, W = len(motif), len(motif[0])
    ay, ax = anchor if anchor is not None else ((H - 1) // 2, (W - 1) // 2)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for y in range(h):
        for x in range(w):
            if grid[y][x] == noise:
                for dy in range(H):
                    for dx in range(W):
                        yy, xx = y + dy - ay, x + dx - ax
                        if 0 <= yy < h and 0 <= xx < w:
                            out[yy][xx] = motif[dy][dx]
    return out


def comps(grid, color):
    """8-connected components of a color as sets of (y,x)."""
    cells=[(y,x) for y,r in enumerate(grid) for x,v in enumerate(r) if v==color]
    out=[]
    while cells:
        s=[cells.pop()]
        cl=set(s)
        while s:
            y,x=s.pop()
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    p=(y+dy,x+dx)
                    if p in cells:
                        cells.remove(p); cl.add(p); s.append(p)
        out.append(cl)
    return out

def norm_shape(comp):
    """Translation-invariant frozenset shape of a component."""
    y0=min(y for y,x in comp); x0=min(x for y,x in comp)
    return frozenset((y-y0,x-x0) for y,x in comp)

def has_2x2(comp):
    """True if the component contains a filled 2x2 block."""
    s=set(comp)
    return any((y,x) in s and (y,x+1) in s and (y+1,x) in s and (y+1,x+1) in s for y,x in s)

def l_stroke(grid, bg=None):
    """The stroke: largest 2x2-free component; returns (color, cells set)."""
    bg=bg if bg is not None else background(grid)
    cc={}
    for c in set(v for r in grid for v in r)-{bg}:
        cc[c]=comps(grid,c)
    best=max((comp for cl in cc.values() for comp in cl if not has_2x2(comp)), key=len)
    return grid[next(iter(best))[0]][next(iter(best))[1]], set(best)

def concave_twin_recolor(grid, bg=None):
    """Recolor to the L-stroke color the shape-twin of the component nested in the L's concave corner."""
    bg=bg if bg is not None else background(grid)
    dst,stroke=l_stroke(grid,bg)
    ys=[y for y,x in stroke]; xs=[x for y,x in stroke]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    cc={c:comps(grid,c) for c in set(v for r in grid for v in r)-{bg}}
    inside=[comp for c,cl in cc.items() if c!=dst for comp in cl
            if all(y0<=y<=y1 and x0<=x<=x1 for y,x in comp) and not (comp & stroke)]
    assert len(inside)==1
    inner=norm_shape(inside[0])
    groups={}
    for c,cl in cc.items():
        if c==dst: continue
        for comp in cl: groups.setdefault(norm_shape(comp),[]).append(comp)
    twins=[m for m in groups[inner] if m!=inside[0]]
    assert len(twins)==1
    out=[row[:] for row in grid]
    for y,x in twins[0]: out[y][x]=dst
    return out

from collections import Counter, deque

def background_color(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def same_color_components(grid, c):
    """4-connected components of a single color as lists of (row, col)."""
    h, w = len(grid), len(grid[0]); seen = set(); out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == c and (i, j) not in seen:
                q = deque([(i, j)]); seen.add((i, j)); comp = []
                while q:
                    y, x = q.popleft(); comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == c and (ny, nx) not in seen:
                            seen.add((ny, nx)); q.append((ny, nx))
                out.append(comp)
    return out

def fill_rect_components(grid, c, min_size=2):
    """Same-color 4-connected components of at least min_size cells: each gets its bounding box filled."""
    return [comp for comp in same_color_components(grid, c) if len(comp) >= min_size]
def components(grid, color):
    """The 4-connected components of cells of the given color, as lists of (row, col)."""
    from collections import deque
    h, w = len(grid), len(grid[0]); seen = set(); out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == color and (i, j) not in seen:
                q = deque([(i, j)]); seen.add((i, j)); cells = []
                while q:
                    y, x = q.popleft(); cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                            seen.add((ny, nx)); q.append((ny, nx))
                out.append(cells)
    return out

def background(grid):
    """The most frequent color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def fill_bounding_boxes(grid, min_size=4):
    """Keep large same-color components as solid rectangles: fill each component of at least min_size cells with its color over its bounding box, and turn every other non-background cell into the background color."""
    from collections import Counter
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    fills = []
    for color in Counter(v for row in grid for v in row):
        if color == bg:
            continue
        for cells in components(grid, color):
            if len(cells) >= min_size:
                ys = [c[0] for c in cells]; xs = [c[1] for c in cells]
                fills.append((min(ys), min(xs), max(ys), max(xs), color))
    for y0, x0, y1, x1, color in fills:
        for i in range(y0, y1 + 1):
            for j in range(x0, x1 + 1):
                out[i][j] = color
    return out


def nonzero_mask(grid):
    """Boolean grid: True where a cell is not 0."""
    return [[v != 0 for v in row] for row in grid]

def mask_and(a, b):
    """Cellwise AND of two same-shape boolean grids (or grids treated as masks: nonzero = True)."""
    return [[av != 0 and bv != 0 for av, bv in zip(ra, rb)] for ra, rb in zip(a, b)]

def recolor_mask(mask, color):
    """A boolean mask as a grid of `color` where True and 0 where False."""
    return [[color if v else 0 for v in row] for row in mask]

def sections(grid):
    """Two sections split around a one-color nonzero frontier row, else column (frontier dropped)."""
    fi = [i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    if fi:
        cut = fi[0]
        return grid[:cut], grid[cut + 1:]
    fj = [j for j in range(len(grid[0])) if len({row[j] for row in grid}) == 1 and grid[0][j] != 0]
    if fj:
        cut = fj[0]
        return [row[:cut] for row in grid], [row[cut + 1:] for row in grid]
    cut = len(grid) - 1
    return grid[:cut], grid[cut + 1:]

def fill_enclosed(grid, new=7):
    """Every enclosed background region filled with `new` (per-region override via area_color)."""
    out = [row[:] for row in grid]
    for reg in enclosed_regions(grid):
        for i, j in reg:
            out[i][j] = new
    return out

def split_regions(grid):
    """The two regions on either side of a one-color full row or column separator."""
    for i, row in enumerate(grid):
        if len(set(row)) == 1:
            return grid[:i], grid[i + 1:]
    for j in range(len(grid[0])):
        if len({r[j] for r in grid}) == 1:
            return [r[:j] for r in grid], [r[j + 1:] for r in grid]


def fill_enclosed_area_parity(grid, even=2, odd=7):
    """Every enclosed background region filled with `even` if its area is even, else `odd`."""
    out = [row[:] for row in grid]
    for reg in enclosed_regions(grid):
        v = even if len(reg) % 2 == 0 else odd
        for i, j in reg:
            out[i][j] = v
    return out

def downsample_majority(grid, factor=3, bg=(0, 5)):
    """Each factor x factor block becomes one cell: the single non-background color in it, else 0."""
    H = len(grid) // factor
    out = [[0] * H for _ in range(H)]
    for bi in range(H):
        for bj in range(H):
            vs = {grid[i][j] for i in range(bi*factor, bi*factor+factor)
                  for j in range(bj*factor, bj*factor+factor) if grid[i][j] not in bg}
            if len(vs) == 1:
                out[bi][bj] = vs.pop()
    return out


def uniform_lines(grid):
    """Indices of the rows and columns that are uniform and non-zero."""
    ur = {i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0}
    uc = {j for j in range(len(grid[0])) if len({r[j] for r in grid}) == 1 and grid[0][j] != 0}
    return ur, uc

def index_runs(idx):
    """A sorted index list as its contiguous runs."""
    out = []
    for i in idx:
        if out and i == out[-1][-1] + 1: out[-1].append(i)
        else: out.append([i])
    return out

def pattern_blocks(grid):
    """The patterned sub-blocks of the grid, split by uniform lines of separator colors (colors appearing only in uniform lines)."""
    ur, uc = uniform_lines(grid)
    h, w = len(grid), len(grid[0])
    sep = {grid[i][0] for i in ur} | {grid[0][j] for j in uc}
    sep = {c for c in sep if all(i in ur or j in uc for i in range(h) for j in range(w) if grid[i][j] == c)}
    rows = [i for i in range(h) if not (i in ur and grid[i][0] in sep)]
    cols = [j for j in range(w) if not (j in uc and grid[0][j] in sep)]
    return [[[[grid[i][j] for j in c] for i in r] for c in index_runs(cols)] for r in index_runs(rows)]

def intersect_blocks(grid, color=2):
    """Cells non-zero in every patterned block, recolored; a single block maps to itself."""
    bl = [b for grp in pattern_blocks(grid) for b in grp
          if any(len(set(row)) > 1 for row in b)]
    if len(bl) == 1:
        return [[color if v else 0 for v in row] for row in bl[0]]
    h, w = len(bl[0]), len(bl[0][0])
    return [[color if all(b[i][j] != 0 for b in bl) else 0 for j in range(w)] for i in range(h)]

def orth_hits(grid, i, j, color):
    """The number of the four orthogonal directions from (i, j) in which `color` appears before the grid edge."""
    H, W = len(grid), len(grid[0])
    hits = 0
    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        k = 1
        while 0 <= i + k * di < H and 0 <= j + k * dj < W:
            if grid[i + k * di][j + k * dj] == color:
                hits += 1
                break
            k += 1
    return hits

